COSTS = "3.25 3.25 3.25 3.25 3.25 3.25 3.25 3.95 3.95 3.95 4.80 4.80 4.80 2.88 3.08 4.80 2.88 4.26 6.46 6.46 6.46 6.86 2.85 4.56 5.46 5.06 5.26 4.76 4.04 4.07 5.79 5.79 5.79 5.57 3.70 6.57 4.75 4.75 5.25 4.00 4.90 4.90 4.20 5.22 5.22 5.22 6.27 4.96".split()
PRICES = "20 20 20 20 20 20 20 22 22 22 31 31 31 24 25 33 22 26 39 39 39 37 26 28 28 28 29 28 34 32 44 44 44 28 24 32 26 24 28 28 30 32 31 30 30 30 31 28".split()
MARGS = "81 81 81 81 81 81 81 79 79 79 82 82 82 86 85 83 85 81 80 80 80 78 87 81 77 79 79 80 86 85 84 84 84 77 82 76 78 77 78 83 81 82 84 79 79 79 76 79".split()

# The catalog's own family blocks, in order, with their counts.
FAMILIES = [("01 חליטות קרות",7),("02 לימונדות",3),("03 סיגנצ'ר",4),("04 גזוז",3),
            ("05 אייס מאצ'ה",6),("06 מאצ'ה ספיישל",5),("07 מאצ'ה קוקוס",5),
            ("08 צ'אי מסאלה",6),("09 קולד פואם",4),("10 אובה",5)]

def rows():
    fam=[]
    for name,n in FAMILIES: fam += [name]*n
    assert len(fam)==48, len(fam)
    return [dict(i=i+1, name=NAMES[i], cost=COSTS[i], price=PRICES[i], marg=MARGS[i], family=fam[i])
            for i in range(48)]
